@app.cell
def _(estimate_interval, mo, pd, selected):
    def stats_table():
        rows = []
        for key, s in selected.items():
            name, col = key.split("::", 1)
            interval = estimate_interval(s.index)
            # 実周期から期待される行数に対して、実際に何割あるか
            if interval is not None and len(s) > 1 and interval.total_seconds() > 0:
                expected = (s.index.max() - s.index.min()) / interval + 1
                coverage = f"{len(s) / expected * 100:.1f}%"
            else:
                coverage = "-"
            rows.append({
                "ファイル": name,
                "列": col,
                "件数": f"{len(s):,}",
                "欠測なし率": coverage,
                "周期": "不明" if interval is None else f"{interval.total_seconds() / 60:.0f}分",
                "最小": round(float(s.min()), 3) if len(s) else None,
                "平均": round(float(s.mean()), 3) if len(s) else None,
                "最大": round(float(s.max()), 3) if len(s) else None,
            })
        return pd.DataFrame(rows)

    mo.ui.table(stats_table(), selection=None) if selected else mo.md("列が選ばれていない。")
    return (stats_table,)


